scenarios.example_code:
import { publishOntology } from '@projexlight/sdk-semantic';
await publishOntology({
  tenant_id, name: 'crm-core', version: '1.0.0',
  object_types: [
    { name: 'Customer', fields: [{ name: 'email', kind: 'string' }, { name: 'plan', kind: 'string' }] },
    { name: 'Invoice',  fields: [{ name: 'amount_cents', kind: 'integer' }, { name: 'paid_at', kind: 'timestamp' }] },
  ],
  relation_types: [
    { name: 'belongs_to', from: 'Invoice', to: 'Customer', cardinality: 'many-to-one' },
  ],
});

import { resolveIntent } from '@projexlight/sdk-semantic';
const { plan, policy_decisions } = await resolveIntent({
  tenant_id, persona_id,
  intent: 'show me top 10 customers by MRR last quarter',
});
// plan is a structured walk of Customer + Invoice ordered by an MRR aggregate.
// policy_decisions explains any allow/deny/reshape rules that fired.

// resolveIntent returns plan with reshaped projection:
// SELECT plan_tier, COUNT(*) FROM customer GROUP BY plan_tier
// rather than SELECT email, payment_method_last4 FROM customer.
// policy_decisions explains why.

import { registerCapability } from '@projexlight/sdk-semantic';
await registerCapability({
  tenant_id, mcp_server: 'projex-registry',
  tool_name: 'projex_registry_search_sdks',
  capability_kind: 'discover-sdk',
  bridges_to: ['ontology.Capability'],
});

// User asks: 'show me invoices by churn'
// Strict policy refuses: 'churn' is not a column in the ontology;
// suggests {plan_tier, billing_status, mrr} as nearby concepts.
